    germanium:{ label: 'Germanium Fuzz',   mode: 'fuzz', drive: 8,    starve: 0,    rect: 0,    tone: 3800,  level: 0.9,  mix: 0.80 },
    silicon:  { label: 'Silicon Fuzz',     mode: 'fuzz', drive: 22,   starve: 0,    rect: 0,    tone: 6800,  level: 0.85, mix: 0.90 },
